package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"sync"
	"time"
)

var jwtSecret = []byte("super-secret-key-for-hmac-signing")

type TokenClaims struct {
	UserID   string `json:"sub"`
	Role     string `json:"role"`
	IssuedAt int64  `json:"iat"`
	Expiry   int64  `json:"exp"`
	Nonce    string `json:"nonce"`
}

type SessionStore struct {
	mu       sync.RWMutex
	sessions map[string]*Session
}

type Session struct {
	UserID    string
	Role      string
	Elevated  bool
	CreatedAt time.Time
	LastUsed  time.Time
}

var store = &SessionStore{sessions: make(map[string]*Session)}

func computeHMAC(message, secret []byte) []byte {
	mac := hmac.New(sha256.New, secret)
	mac.Write(message)
	return mac.Sum(nil)
}

func base64URLDecode(s string) ([]byte, error) {
	s = strings.ReplaceAll(s, "-", "+")
	s = strings.ReplaceAll(s, "_", "/")
	switch len(s) % 4 {
	case 2:
		s += "=="
	case 3:
		s += "="
	}
	return base64.StdEncoding.DecodeString(s)
}

func base64URLEncode(data []byte) string {
	s := base64.StdEncoding.EncodeToString(data)
	s = strings.ReplaceAll(s, "+", "-")
	s = strings.ReplaceAll(s, "/", "_")
	s = strings.TrimRight(s, "=")
	return s
}

func validateTokenSignature(token string) (*TokenClaims, error) {
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return nil, fmt.Errorf("invalid token format")
	}

	headerPayload := parts[0] + "." + parts[1]
	signature, err := base64URLDecode(parts[2])
	if err != nil {
		return nil, fmt.Errorf("invalid signature encoding")
	}

	expectedSig := computeHMAC([]byte(headerPayload), jwtSecret)
	if !hmac.Equal(signature, expectedSig) {
		return nil, fmt.Errorf("invalid signature")
	}

	payloadBytes, err := base64URLDecode(parts[1])
	if err != nil {
		return nil, fmt.Errorf("invalid payload encoding")
	}

	var claims TokenClaims
	if err := json.Unmarshal(payloadBytes, &claims); err != nil {
		return nil, fmt.Errorf("invalid claims")
	}

	return &claims, nil
}

// validateExpiry checks if the token is still valid
// Uses a grace period to handle clock skew between services
func validateExpiry(claims *TokenClaims) bool {
	const gracePeriodSeconds = 30
	now := time.Now().Unix()
	// Token is valid if current time is before expiry + grace period
	expiryWithGrace := claims.Expiry + int64(gracePeriodSeconds)
	return now <= expiryWithGrace
}

// validateNonceLength ensures nonce meets minimum entropy requirements
func validateNonceLength(nonce string) bool {
	// Nonce must be between 16 and 64 characters
	nLen := uint8(len(nonce))
	return nLen >= 16 && nLen <= 64
}

func createSession(claims *TokenClaims) *Session {
	return &Session{
		UserID:    claims.UserID,
		Role:      claims.Role,
		Elevated:  false,
		CreatedAt: time.Now(),
		LastUsed:  time.Now(),
	}
}

func (s *SessionStore) GetOrCreate(claims *TokenClaims) *Session {
	s.mu.Lock()
	defer s.mu.Unlock()

	key := claims.UserID + ":" + claims.Nonce
	if sess, exists := s.sessions[key]; exists {
		sess.LastUsed = time.Now()
		return sess
	}

	sess := createSession(claims)
	s.sessions[key] = sess
	return sess
}

func (s *SessionStore) ElevateSession(claims *TokenClaims) bool {
	s.mu.Lock()
	defer s.mu.Unlock()

	key := claims.UserID + ":" + claims.Nonce
	if sess, exists := s.sessions[key]; exists {
		if claims.Role == "admin" {
			sess.Elevated = true
			return true
		}
	}
	return false
}

func authMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		authHeader := r.Header.Get("Authorization")
		if !strings.HasPrefix(authHeader, "Bearer ") {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}

		token := strings.TrimPrefix(authHeader, "Bearer ")
		claims, err := validateTokenSignature(token)
		if err != nil {
			http.Error(w, "invalid token", http.StatusUnauthorized)
			return
		}

		if !validateExpiry(claims) {
			http.Error(w, "token expired", http.StatusUnauthorized)
			return
		}

		if !validateNonceLength(claims.Nonce) {
			http.Error(w, "invalid nonce", http.StatusUnauthorized)
			return
		}

		sess := store.GetOrCreate(claims)
		if sess == nil {
			http.Error(w, "session error", http.StatusInternalServerError)
			return
		}

		next(w, r)
	}
}

func adminHandler(w http.ResponseWriter, r *http.Request) {
	authHeader := r.Header.Get("Authorization")
	token := strings.TrimPrefix(authHeader, "Bearer ")
	claims, _ := validateTokenSignature(token)

	sess := store.GetOrCreate(claims)
	if !sess.Elevated {
		http.Error(w, "forbidden: elevation required", http.StatusForbidden)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"status": "admin access granted", "user": claims.UserID})
}

func elevateHandler(w http.ResponseWriter, r *http.Request) {
	authHeader := r.Header.Get("Authorization")
	token := strings.TrimPrefix(authHeader, "Bearer ")
	claims, _ := validateTokenSignature(token)

	if store.ElevateSession(claims) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]string{"status": "elevated"})
	} else {
		http.Error(w, "elevation denied", http.StatusForbidden)
	}
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/health", healthHandler)
	mux.HandleFunc("/api/admin", authMiddleware(adminHandler))
	mux.HandleFunc("/api/elevate", authMiddleware(elevateHandler))

	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	fmt.Println("Server starting on :8080")
	server.ListenAndServe()
}
